/* ---------- content ---------- */
var UNK=function(s){return '<p class="fine">'+s+'</p>'};
var CHAOS=["control","left_ramp","right_ramp","right_orbit","helipad"];
var ALL=["control","upper_loop","side_ramp","left_ramp","spinner","right_ramp","right_orbit","helipad"];
var SECTIONS=[
/* ====== LAYOUT AND BASICS ====== */
{g:"Layout and basics",id:"layout",title:"Playfield layout",steps:[
 {t:"The goal",h:[["main_gate",0,"alt"],["visitor",0,"alt"],["rescue",0,"alt"],["truck",0,"alt"]],b:"<p>Nedry's virus has plunged the park into chaos. Rescue as many staff as you can, capture the dinosaurs, survive the park and eventually escape.</p><p>The island map in the middle of the playfield shows your route through the paddocks.</p>"},
 {t:"White arrows and left ramp",h:["map_panel","left_ramp",["trex",0,"alt"],["left_panel",0,"alt"]],b:"<p>Shoot lit white arrows to spell MAP, then the left ramp to enter a paddock.</p><p>The T-Rex stands over the left ramp, which also starts T-Rex Events.</p>"},
 {t:"Truck and Set Trap targets",h:["truck","trap_l","trap_r",["map_nav",0,"alt"],["turn_ins",0,"alt"]],b:"<p>Shoot the truck to spell T-REX and to choose the left or right path through the paddocks. Set Trap targets sit on both sides of the truck.</p>"},
 {t:"CHAOS shots",h:CHAOS.concat([["chaos_ins",0,"alt"]]),b:"<p>Five shots are marked with the letters of CHAOS. Spell it in order, then hit the target between the bumpers for Chaos Multiball.</p>"+UNK("The rulesheet does not say which shots carry the letters. I read each letter as belonging to the arrow above it. The C lane has its letter above the arrow instead.")},
 {t:"Raptor Pen",h:["raptor_pen",["raptor_ins",0,"alt"],["bolts",0,"alt"],["capture_ins",0,"alt"]],b:"<p>Complete the pen's standup targets to light Raptor Capture at the center target. More shots weaken the fence until Raptor Tri-Ball starts at the dead-end lane.</p><p data-ed=\"premium\">On these models the pen can lock a ball, behind a motorized gate.</p>"},
 {t:"Raptor",ed:"premium",h:["raptor_toy","raptor_pen"],b:"<p>Stern lists an interactive Raptor and Raptor Pen with a ball lock guarded by a motorized gate.</p>"+UNK("The rulesheet says when balls lock here, but not how the Raptor moves.")},
 {t:"Upper flipper shots",h:["upper_flipper","side_ramp","upper_loop"],b:"<p>Making an upper loop then side ramp combo awards 3x the side ramp points and counts as two side ramp shots.</p>"+UNK("The rulesheet does not say which flipper feeds which shot. The upper flipper link is my reading of the lines of the arrows.")},
 {t:"Pop bumpers",h:["bumpers","pop_target",["pop_ins",0,"alt"]],b:"<p>The bumpers build your Amber Bonus. Collect it at the lit pops standup, which is lit by the rollover above the pops. This target also launches the Smart Missile and starts Chaos Multiball.</p>"+UNK("I could not place the rollover above the pops, so it is not marked.")},
 {t:"Right side",h:["right_ramp","right_orbit","helipad",["helipad_sign",0,"alt"],["ramp_panel",0,"alt"],["helicopter",0,"alt"]],b:"<p>Shoot the right ramp enough times for Pteranodon Attack. The Extra Ball is collected here when lit.</p><p>The helipad is needed to capture dinosaurs in harder paddocks.</p>"},
 {t:"Left side",h:["control",["control_ins",0,"alt"],"spinner",["ladder",0,"alt"],["supply",0,"alt"],["purple",0,"alt"]],b:"<p>The Control Room shot starts Control Room modes when lit. The spinner value rises with shots to the four ramps, shown on the printed ladder.</p><p>Hit the three purple standups, then the large standup near the side ramp, for a Supply Drop.</p>"},
 {t:"Lower playfield",h:[["inlane_l",0,"alt"],["inlane_r",0,"alt"],["escape_ins",0,"alt"],["nedry_ins",0,"alt"],["lite2x",0,"alt"],["play2x",0,"alt"]],b:"<p>Inlanes hold the Smart Missile and Super Spinner when lit. Outlanes can save the ball, with Escape on the left and Nedry on the right. The Light 2x Scoring standup starts 2x scoring once lit by a Supply Drop.</p>"}
]},
{g:"Layout and basics",id:"skill",title:"Skill shots",steps:[
 {t:"The sequence",h:[["plunger",0,"alt"],["left_ramp",1],["right_ramp",2],["side_ramp",3],["right_orbit",4]],b:"<p>After a full plunge, shoot the left ramp, right ramp, side ramp, then right orbit. The base value is 2M, and each shot awards 2x, 4x and 6x the base and 3 more seconds of ball save. Completing all four also lights Escape at the left outlane.</p><p>Any skill shot raises the base by 1M for the next ball's skill shot.</p>"+UNK("The rulesheet lists four shots but three multipliers. It does not say what the first scores, or which three the multipliers belong to.")},
 {t:"While lit",h:[["left_ramp",0,"alt"],["right_ramp",0,"alt"],["side_ramp",0,"alt"],["right_orbit",0,"alt"]],b:"<p>These shots will not start modes qualified on the prior ball. They still collect CHAOS letters and rescues if lit, and the Extra Ball can be collected at the right ramp.</p>"},
 {t:"Secret skill shots",h:[["control",0],["right_orbit",0],["pop_target",0]],b:"<p>Plunge lightly so the ball lands on either flipper, then right away make one of these:</p><ul><li><b>C lane:</b> 6M and 3 seconds of ball save.</li><li><b>O lane:</b> 8M and 3 seconds of ball save.</li><li><b>Pops standup:</b> 10M and 3 seconds of ball save.</li><li><b>Pops standup from the right flipper:</b> 20M, 12 seconds of ball save and a higher Amber value.</li></ul>"},
 {t:"MXV skill shot",h:[["left_ramp",1],["right_ramp",2],["upper_loop",3],["side_ramp",4]],b:"<p>Make the upper loop immediately before the side ramp in the normal sequence. The side ramp then scores 8x the initial shot instead of 4x, as a Super Skill Shot, with a 2-way combo worth at least 2M.</p>"}
]},
/* ====== PADDOCKS ====== */
{g:"Paddocks",id:"paddocks",title:"Paddock modes",steps:[
 {t:"Advancing",h:["map_panel","left_ramp","truck",["map_nav",0,"alt"]],b:"<p>Shoot white arrows to spell MAP and light Advance Paddock. The first paddock needs one white arrow shot, and later ones need three. Shoot the left ramp when lit. Shoot the truck to change between the left and right paths.</p><p>The ball is held at the left inlane while the paddock's information shows.</p>"},
 {t:"Three goals",h:[["rescue",0,"alt"],["trap_l",0,"alt"],["trap_r",0,"alt"],["helipad",0,"alt"]],b:"<ol><li>Rescue a set number of staff.</li><li>Set the trap at the Set Trap targets, and visit the helipad in harder paddocks.</li><li>Capture the dinosaur by shooting the flashing yellow and green shot.</li></ol><p>Capturing your first dinosaur lights Control Room. A Smart Missile can also clear a paddock instantly.</p>"},
 {t:"Rescues",h:["rescue"],b:"<p>Lit red shots are staff in danger. The moving green arrow is the dinosaur, which moves toward the closest lit rescue at a speed set by its aggression. If it reaches a lit rescue before you do, the arrow blinks faster until the staff member is injured and that rescue goes out.</p><p>Shooting the dinosaur's shot pauses it for a few seconds, even if no rescue is lit there. Super Tranquilizer at the action button also slows it.</p>"},
 {t:"Rescue streak and Perfect Paddock",h:[["rescue",0,"alt"]],b:"<p>Each rescue scores according to your current streak. Clearing a whole paddock without missing any rescues scores Perfect Paddock, worth 2x the bounty and +1x to the Amber Bonus. You can keep collecting rescues after the capture.</p>"},
 {t:"Rescue milestones",h:[["rescue",0,"alt"],["inlane_l",0,"alt"],["inlane_r",0,"alt"],["ramp_panel",0,"alt"]],b:"<p>Total rescues across your game qualify awards:</p><ul><li><b>3:</b> Light Inlanes</li><li><b>6:</b> Light Extra Ball</li><li><b>8:</b> Light Inlanes</li><li><b>13:</b> +1x Bonus X</li><li><b>15:</b> Light Inlanes</li><li><b>24:</b> Light Inlanes</li><li><b>30:</b> Fossil</li></ul><p>Capturing the Ankylosaurus lowers the Light Inlanes thresholds, which then also depend on when you last lit them.</p>"+UNK("The rulesheet lists 22 rescues with its award unknown.")},
 {t:"Setting the trap",h:["trap_l","trap_r",["helipad",0,"alt"]],b:"<p>After the minimum rescues, the Set Trap targets light. Easier paddocks need one. Harder ones need both, or both in order. Harder paddocks also need a helipad shot, with a short timer to capture before you must shoot the helipad again to refuel.</p><p>If all staff are rescued or injured, the dinosaur moves back to its start and escapes, with no bounty or perk. Keep some staff left as a distraction. If none are left but you still need rescues to set the trap, the trap lights anyway for a short window.</p>"},
 {t:"Dinosaur traits",h:[["rescue",0,"alt"]],b:"<ul><li><b>Diet:</b> carnivores go straight to the nearest staff, while herbivores wander.</li><li><b>Aggression:</b> how fast the green arrow moves.</li><li><b>Bounty:</b> points for the capture.</li><li><b>Amber Bonus:</b> a multiplier on the next Amber Bonus you collect.</li><li><b>Perk:</b> lasts for the rest of the game.</li><li><b>Bonus X:</b> capturing a Super Predator raises it.</li></ul><p>Super Predators are up the middle of the map, and you can skip them by positioning the truck.</p>"}
]},
{g:"Paddocks",id:"dinos",title:"Paddock list",steps:[
 {t:"Level 1",h:["p_galli","p_brach"],b:"<p>Light Set Trap with 1 rescue. Both targets lit, shoot 1. No helipad needed, and 2 adjacent shots are lit to capture. 5 staff, 2.5M bounty, +4x Amber.</p><ul><li><b>Gallimimus (left):</b> omnivore, low aggression. Perk: 2x bounties.</li><li><b>Brachiosaurus (right):</b> omnivore, very low aggression. Perk: +200K rescue streaks.</li></ul>"},
 {t:"Level 1.5: Spitter",h:["p_spit"],b:"<p>Light Set Trap with 2 rescues. Both targets lit, shoot 1. Dilophosaurus, carnivore, medium aggression. It immobilizes staff, preventing their rescue for 5 seconds. 7 staff, 5M bounty, +5x Amber, +1x Bonus X.</p><p><b>Perk:</b> +2x Super Spinner.</p>"},
 {t:"Level 2",h:["p_tric","p_anky"],b:"<p>Light Set Trap with 2 rescues. Both targets lit, shoot 1. Herbivores, medium aggression. 6 staff, 7.5M bounty, +5x Amber.</p><ul><li><b>Triceratops (left):</b> Perk: easier Loop Awards, 1 fewer per award.</li><li><b>Ankylosaurus (right):</b> Perk: 1 fewer rescue for Light Inlanes.</li></ul>"},
 {t:"Level 2.5: T-Rex",h:["p_trex"],b:"<p>Light Set Trap with 2 rescues. Shoot both targets. Carnivore, extreme aggression. 8 staff, 7.5M bounty and an Extra Ball, +6x Amber, +1x Bonus X.</p><p><b>Perk:</b> +8 seconds to all timers.</p>"},
 {t:"Level 3",h:["p_steg","p_comp"],b:"<p>Light Set Trap with 2 rescues. Shoot both targets. Medium aggression. 7 staff, 10M bounty, +6x Amber.</p><ul><li><b>Stegosaurus (left):</b> herbivore. Perk: +15K per pop to Amber.</li><li><b>Compsognathus (right):</b> carnivore, cannot be stunned. Perk: +250K combos.</li></ul>"},
 {t:"Level 3.5: Spinosaurus",h:["p_spin"],b:"<p>Light Set Trap with 3 rescues. Shoot the left target, then the right. Carnivore, very high aggression. It can jump from one side of the island to the other. 10 staff, 10M bounty, +7x Amber, +1x Bonus X.</p><p><b>Perk:</b> lights King of the Island Multiball.</p>"},
 {t:"Level 4",h:["p_pter","p_rapt",["visitor",0,"alt"]],b:"<p>Light Set Trap with 2 rescues. Shoot the left target, then the right. Carnivores, high aggression. 10 staff, 12.5M bounty, +7x Amber.</p><ul><li><b>Pteranodon (left):</b> jumps directly to any flashing rescue shot. Perk: 2x Chaos jackpots.</li><li><b>Raptor (right):</b> hunts in a pack of 2, so complete the capture twice. The bounty includes 2.5M for the first raptor. Super Tranquilizer stuns both. Perk: 2x Raptor jackpots.</li></ul><p>After leaving either Level 4 paddock, spelling MAP again lights the left ramp for Visitor's Center.</p>"}
]},
/* ====== T-REX ====== */
{g:"T-Rex Events",id:"trex",title:"T-Rex Events",steps:[
 {t:"Starting an event",h:["truck","left_ramp",["turn_ins",0,"alt"],["left_panel",0,"alt"]],b:"<p>Shoot the truck to complete T-REX and light the left ramp. The first two events award letters for any truck hit, and later events need a full turn of the truck.</p><p>On default settings, Feed T-Rex is always first. The others then cycle with truck shots: Chase, Encounter, Rampage.</p><p data-ed=\"premium\">A lit left ramp literally feeds the animatronic T-Rex on these models.</p><p data-ed=\"pro\">The Pro holds the ball with the left inlane up-post during the introduction.</p>"+UNK("The Basics section says three truck hits start the first event, and four after that. The T-Rex Events section does not give counts.")},
 {t:"Rewards and limits",h:[["trex",0,"alt"],["museum",0,"alt"]],b:"<p>Completing any single-ball event awards a Fossil and 1M per second remaining. Other non-Control Room modes and one multiball may start during a non-multiball event.</p><p>Play all four events to qualify Museum Mayhem. After that, Feed T-Rex is the only event offered, and it gets harder to start each time.</p>"},
 {t:"Feed T-Rex",h:["left_ramp",["trex",0,"alt"]],b:"<p>A single-ball hurry-up that turns into a 2-ball multiball. On default settings it starts immediately after spelling T-REX. A 500K hurry-up is lit at the left ramp with a 20 second timer.</p><p>Shoot orange arrows to raise the hurry-up, up to 6.75M, and reset the timer. Each orange shot then goes out. Shoot the left ramp to collect and start T-Rex Multiball.</p>"},
 {t:"T-Rex Multiball",h:CHAOS.concat(["left_ramp"]),b:"<p>All 5 CHAOS shots are lit for jackpots, starting at the hurry-up value you collected. Each adds 250K to the next, and +1x if shot from left to right, shown by red jackpots.</p><p>After all 5, a Super Jackpot at the left ramp scores the sum of the jackpots. It relights them and resets the multiplier.</p>"},
 {t:"T-Rex Chase",h:["truck"],b:"<p>Alternate a single orange flashing shot, for 3M (+3M), with the truck to shift gears, for 1M (+1M). A dodge within 3 seconds of a shift scores double. A collected dodge shot is not available again. Complete this 5 times to finish and earn a Fossil.</p>"},
 {t:"T-Rex Encounter",h:[["truck",1],["left_ramp",0],["helipad",0,"alt"],["spinner",0,"alt"],["right_ramp",0,"alt"],["right_orbit",0,"alt"]],b:"<p>Shoot the truck for 2M. Then alternate orange arrows (4M, 8M, 11M) to free a worker, with the left ramp (5M) to distract the T-Rex.</p><p>The helipad and center spinner score 1x, the right ramp 2x and the right orbit 3x. Free three workers to finish and earn a Fossil.</p>"},
 {t:"T-Rex Rampage",h:["left_ramp","right_ramp",["side_ramp",0,"alt"],["helipad",0,"alt"]],b:"<p>Shoot the left or right ramp to lower the T-Rex, then the left ramp for 10M (+5M per left ramp shot). Shooting the Raptor Tower first multiplies the award by 3x, and the helipad by 2x. The two stack for 6x.</p><p>Repeat until the timer ends. Three completions earn a Fossil when the timer expires or you drain.</p>"}
]},
/* ====== CONTROL ROOM ====== */
{g:"Control Room",id:"control",title:"Control Room modes",steps:[
 {t:"Lighting Control Room",h:["control",["control_ins",0,"alt"]],b:"<p>Control Room is lit by:</p><ul><li>Capturing your first dinosaur</li><li>Spelling CHAOS twice</li><li>A jackpot in Raptor Tri-Ball</li><li>15 tower shots</li></ul><p>The lit shot catches the ball with the up-post and you choose one of three timed modes. Modes already played are greyed out. After all three, the next shot starts Secure Control Room.</p><p>Completing a mode awards a Fossil and 1M per second remaining. Other non-T-Rex modes and one multiball may start during one.</p>"},
 {t:"Virus Attack",h:["control"],b:"<p>Shoot any lit shot (3M, 4M, then 5M) to light the Control Room for 10M plus the shot values collected so far. Do this three times. The third Control Room shot finishes the mode.</p>"},
 {t:"Restore Power",h:[["spinner",1]].concat(["control","upper_loop","side_ramp","left_ramp","right_ramp","right_orbit","helipad"]),b:"<p>Shoot the spinner for 3M, which lights all other shots. Then shoot the other seven. Each is worth 3M + 50K per spin during the mode, times the number of shots made. The last shot finishes the mode.</p>"+UNK("The rulesheet does not list the seven. These are the seven other arrows.")},
 {t:"System Boot: left ramp set",h:[["left_ramp",1],["right_ramp",2],["helipad",2],["right_orbit",2],["pop_target",2]],b:"<p>Left ramp (5M), then one of right ramp (8M), helipad (12M), right orbit (15M) or amber target (15M).</p>"},
 {t:"System Boot: helipad set",h:[["helipad",1],["left_ramp",2],["spinner",2],["control",2],["raptor_pen",2]],b:"<p>Helipad (7M), then one of left ramp (6M), spinner (8M), Control Room (15M) or Raptor Pit (20M).</p>"},
 {t:"System Boot: spinner set",h:[["spinner",1],["supply",2],["upper_loop",2],["side_ramp",2]],b:"<p>Spinner (9M), then one of Supply Drop (15M), loop (20M) or Raptor Tower (25M). Complete all three sets to light the Control Room for the sum of the second shots plus 1M per second remaining, and a Fossil.</p>"},
 {t:"Invalid Frenzy",h:["control","raptor_pen"],b:"<p>A hidden four-ball multiball. It is awarded if all three modes have been played and you light and start it by a method not yet used, or by choosing ??INVALID?? on the Smart Missile.</p><p>A number of switch hits qualifies the jackpot at the Control Room, with major switches building its value faster than minor ones. Once collected, the Control Room relights for a triple jackpot. After that, relighting takes more switches.</p><p>Any switch in the Raptor Pen builds toward an add-a-ball.</p>"}
]},
/* ====== MULTIBALLS ====== */
{g:"Multiballs",id:"chaos",title:"Chaos Multiball",steps:[
 {t:"Starting",h:CHAOS.concat(["pop_target",["chaos_ins",0,"alt"]]),b:"<p>Collect the CHAOS letters in order to light the pops target for Chaos Multiball. Later attempts need two spellings, with other awards such as points or lighting Control Room replacing the first.</p><p>Supply Drop can also award letters, and a Smart Missile can complete the word in one shot.</p>"},
 {t:"Phase 1: jackpots by side",h:["truck","pop_target"],b:"<p>3 balls. Jackpots light on one half of the playfield, set by the truck's direction. Each can only be collected once until a super jackpot or a truck hit. Hit the truck to switch sides and light the other side's jackpots.</p><p>The more you collect on one side before switching, the more they are worth, which also builds the super jackpot.</p>"},
 {t:"Phase 1: super jackpots",h:["pop_target",["truck",0,"alt"]],b:"<p>The first super jackpot lights at the amber target after 1 jackpot. The second and third need 2, and the fourth and fifth need 3. With at most 1 jackpot still lit, a lit super jackpot can also be collected with a full turn of the truck.</p><p>Each awards the jackpots collected since the last one, and one CHAOS letter.</p>"},
 {t:"Phase 2: letters",h:CHAOS.concat(["pop_target"]),b:"<p>Collect all 5 super jackpots, across attempts, to light the five letter shots in any order. Each is worth the base value of that letter's super jackpot. Scoring at least one awards a Fossil at the end of the multiball.</p><p>After all five, the pop bumper target scores the Chaos Hurry-Up, worth all the letters combined. It is doubled with the truck facing left. Collecting it restarts at phase 1.</p>"},
 {t:"Add-a-ball",h:["bumpers"],b:"<p>Hitting the pops launches another ball with a short ball saver. The first takes 10 pops, and each one takes 10 more than the last.</p><p>Supply Drops do not award add-a-balls in this mode, but you can claim one in the grace period after it ends.</p>"}
]},
{g:"Multiballs",id:"raptor",title:"Raptor Tri-Ball",steps:[
 {t:"Starting",h:["raptor_pen",["bolts",0,"alt"],["capture_ins",0,"alt"]],b:"<p>Complete the pen's standups twice (+1 per later attempt) to light Raptor Capture at the center target. A shot to the dead-end lane counts as completing all of them.</p><p>After capture, more shots weaken the fence. At 0%, one last dead-end shot starts the multiball. The first starts with the fence at 50%, and dead-end shots lower it more. The lightning bolts flash when it is ready. A Smart Missile can also start it.</p>"},
 {t:"Phase 1: Raptor jackpots",h:["left_ramp","right_ramp"],b:"<p>5M + 15K per switch. The left and right ramps are lit red, and the second ramp scores double the current value.</p>"},
 {t:"Phase 2: CHAOS jackpots",h:CHAOS,b:"<p>2M + 15K per switch. Every CHAOS letter collects the current jackpot.</p>"},
 {t:"Phase 3: Super CHAOS",h:["right_ramp","upper_loop"],b:"<p>3 balls are added, up to 6 in play. Two red arrows are lit for super jackpots:</p><ul><li><b>Right ramp:</b> 2x chaos jackpot x balls in play.</li><li><b>Upper loop:</b> 3x chaos jackpot x balls in play.</li></ul><p>Either also awards a Fossil.</p>"},
 {t:"Phase 4: Raptor Rampage",h:CHAOS.concat(["raptor_pen"]),b:"<p>2M + 15K per switch. All CHAOS shots are lit red. Each goes out when collected, and a dead-end lane shot relights them. Each full wave scores a super jackpot worth the wave's total. This lasts for the rest of the multiball.</p>"},
 {t:"All phases: 2x jackpots",h:["raptor_pen"],b:"<p>Hit all three pen targets, then the dead-end lane, to double all jackpots for 15 seconds.</p><p data-ed=\"premium\">Hitting the captive ball resets the 15 second timer.</p><p data-ed=\"pro\">The same rule applies to get 2x scoring, but the ball cannot be locked on the Pro.</p>"}
]},
{g:"Multiballs",id:"koti",title:"King of the Island",steps:[
 {t:"King of the Island Multiball",h:["p_spin","left_ramp"].concat(ALL.filter(function(s){return s!=="left_ramp"})),b:"<p>Capture the Spinosaurus to qualify this at the left ramp. It must be played before the next paddock and takes priority over all other features.</p><p>A 3-ball switch-based multiball. Reach a switch threshold to light all major shots, then shoot one for a 1x jackpot. Repeat, and all major shots except those collected light for +1x, up to 5x. After locking in a jackpot, you must reshoot your earlier jackpot shots to requalify the switch phase.</p><p>Each jackpot's color shows its multiplier, in rainbow order starting at red.</p>"+UNK("The rulesheet does not list the major shots. The eight arrows are marked.")}
]},
/* ====== OTHER ====== */
{g:"Other features",id:"missile",title:"Smart Missile",steps:[
 {t:"Launching",h:["inlane_l","pop_target"],b:"<p>Enough rescues light the left inlane. The next time the ball rolls through, the up-post holds it and calls for a shot to the pops standup. You have 3 seconds to pick an award with the action button. A good shot scores it, plus 10M (+5M for each successful Smart Missile so far this game).</p><p>Smart Missile alternates with Super Spinner on truck hits.</p>"},
 {t:"Choices 1 and 2",h:[["pop_target",0,"alt"]],b:"<p><b>Choice 1:</b> Light Outlanes, or Super Supply Drop if outlanes are already lit. Do not pick Super Supply Drop if one is already ready. It will just collect that one and unlight the target.</p><p><b>Choice 2:</b> Clear Paddock if the current dinosaur is not captured, otherwise Super Combos, which score 5x for the rest of the ball.</p>"},
 {t:"Choices 3 and 4",h:[["pop_target",0,"alt"]],b:"<p>The first 2 available of these. The first four can only be collected once per game.</p><ul><li>+5 Rescues</li><li>Raptor Multiball (not while Feed T-Rex is running, CHAOS is ready or any multiball is running)</li><li>Extra Ball</li><li>Fossil</li><li>+10 Rescues</li><li>Super Escape: for the rest of the ball, Light Escape does not need qualifying at the pops switch</li></ul>"},
 {t:"Choices 5 and 6",h:[["pop_target",0,"alt"]],b:"<p><b>Choice 5:</b> the first available of ??Invalid??, Complete CHAOS (5 letters) or 25M.</p><p><b>Choice 6:</b> Abort. This deactivates the missile, and the inlane insert flashes instead of staying solid. Two truck shots requalify it.</p>"}
]},
{g:"Other features",id:"spinner",title:"Spinner and Pteranodon",steps:[
 {t:"Spinner value",h:["spinner","ladder",["left_ramp",1],["helipad",2],["right_ramp",3],["side_ramp",4]],b:"<p>Each ramp raises the spinner from a base of 30K per spin:</p><ul><li>Left ramp: 15K</li><li>Helipad: 30K</li><li>Right ramp: 50K</li><li>Tower: 100K</li></ul><p>With all four, the spinner is 225K per spin. One spinner shot collects the value, then it resets.</p>"},
 {t:"Super Spinner",h:["inlane_r","spinner"],b:"<p>Enough rescues light the right inlane. Rolling through multiplies each spin by your Bonus Multiplier for a limited time, +2x if the Spitter was captured. The lit inlane goes out when the ball drains, and alternates with Smart Missile on truck hits.</p>"},
 {t:"Pteranodon Attack",h:["right_ramp",["ramp_panel",0,"alt"]],b:"<p>Starts after four right ramp shots. A timed frenzy where all switches add 25K (+10K each later Attack) to an award collected at the right ramp, which you can rebuild and recollect while time remains. Every 12 switches adds a multiplier to your next award.</p><p>The multiplier resets on collecting or draining, and carries over only if the mode times out. Its timer does not pause in the pops.</p>"},
 {t:"Fossil links",h:[["right_ramp",0,"alt"]],b:"<p>Completing Fossil Set 1 adds +10x to the next Pteranodon Attack. Collecting an award of 50M or more gives a wildcard Fossil.</p>"}
]},
{g:"Other features",id:"counts",title:"Loop and Tower awards",steps:[
 {t:"Loop Awards",h:["upper_loop"],b:"<p>Loop shots count up through the game:</p><ul><li><b>3, 13, 23 and so on:</b> qualifies Super Supply Drop</li><li><b>8, 18, 38 and so on:</b> rising points</li><li><b>28:</b> wildcard Fossil</li></ul><p>With the Triceratops captured, awards come every 4 loops instead of every 5.</p>"},
 {t:"Tower Awards",h:["side_ramp",["tower",0,"alt"]],b:"<p>Side ramp shots count up:</p><ul><li><b>5:</b> 3M</li><li><b>10:</b> 5M</li><li><b>15:</b> Light Control Room</li><li><b>20:</b> 15M</li><li><b>25:</b> wildcard Fossil</li><li><b>35, 45, 55 and so on:</b> 15M</li></ul>"},
 {t:"Super Tranquilizer",h:[["side_ramp",0,"alt"]],b:"<p>Each side ramp award also qualifies Super Tranquilizer at the action button. When it is lit green in a paddock, press it to stun the dinosaur for a moment. It must be requalified after one use.</p>"+UNK("The action button is on the lockbar, outside this photo crop.")}
]},
{g:"Other features",id:"amber",title:"Amber Bonus and Supply Drop",steps:[
 {t:"Amber Bonus",h:["bumpers","pop_target",["pop_ins",0,"alt"]],b:"<p>The bumpers build it through the whole game. Collect it at the lit pops standup, which the rollover above the pops lights. Collecting does not reset it, so it relights and keeps growing.</p><p>Capturing dinosaurs adds multipliers to your next collect, with +1x for Perfect Paddocks. They stack until collected. It also collects in the end-of-ball bonus, so any built multiplier is used then and does not carry to the next ball.</p><p>Fossil Set 3 adds a 10x multiplier.</p>"},
 {t:"Supply Drop",h:["purple","supply"],b:"<p>Shoot the flashing blue targets to light the Supply Drop target for a mystery award. Possible awards:</p><ul><li>Add-a-ball (first Supply Drop during Feed T-Rex or Raptor Tri-Ball)</li><li>Advance CHAOS</li><li>Advance MAP</li><li>Light Advance Paddock</li><li>5M</li><li>Max Spinner</li><li>Double Nedry value</li><li>Spot Rescue</li><li>Set Trap</li><li>Call Helicopter</li></ul><p>Add-a-balls can be collected during any multiball this way, except Chaos.</p>"},
 {t:"2x Scoring",h:["lite2x",["play2x",0,"alt"],["supply",0,"alt"]],b:"<p>Collecting either type of Supply Drop lights the Light 2x Scoring standup, for double scoring for 45 seconds.</p>"},
 {t:"Super Supply Drop",h:["supply",["upper_loop",0,"alt"]],b:"<p>Qualified at the Supply Drop target after 3 (+10) loops, or by Smart Missile. It flashes rather than staying solid, and takes priority. Only one can be qualified at once, so collect it before the next threshold. Awards in order:</p><ol><li>Amber Frenzy #1 (3 loops)</li><li>Amber Frenzy #2 (13)</li><li>Amber Frenzy #3 (23)</li><li>Amber Frenzy #4 (33)</li><li>Goat Mania, if logged in, otherwise the next award (43)</li><li>Extra Ball (53)</li><li>Super Escape (63)</li><li>Collect 3x Bonus (73)</li><li>Super Inlanes for the rest of the ball (83)</li></ol>"+UNK("The Extra Balls section calls this the 5th Super Supply Drop, while this table lists it 6th. Skipping Goat Mania would explain that, but the rulesheet does not say so.")},
 {t:"Amber Frenzy and Goat Mania",h:["bumpers",["left_ramp",0,"alt"],["right_ramp",0,"alt"]],b:"<p>The first four Super Supply Drops are timed modes in random order, each collecting your Amber Bonus on certain shots:</p><ul><li>Amber Pops: 20 seconds</li><li>Amber Slings: 30 seconds</li><li>Amber Targets: 40 seconds</li><li>Amber Ramps: 50 seconds</li></ul><p><b>Goat Mania:</b> for 40 flips, all Amber Frenzy features run, and every Amber switch plays a goat sound. With the topper installed, it can also start by spelling JURASSIC PARK on the topper with paddock completions.</p>"}
]},
{g:"Other features",id:"combos",title:"Combos",steps:[
 {t:"DNA Combo rules",h:ALL,b:"<p>There are 11 unique DNA Combos. Each scores points (1M base) and raises all other combos, adds 400K to the bonus, lights an Extra Ball at 6 (adjustable) and gives a wildcard Fossil at 11.</p><p>A wrong lane, target or bumper breaks a combo, but a drain or slingshot does not. There is no time limit. A new one can only start after the last is completed or broken.</p>"},
 {t:"Combos from the spinner",h:[["spinner",1],["side_ramp",2],["upper_loop",2],["truck",3],["supply",3],["lite2x",3]],b:"<ul><li><b>Gallimimus:</b> spinner, truck</li><li><b>T-Rex:</b> spinner, tower ramp, truck</li><li><b>Compsognathus:</b> spinner, tower ramp, 2x playfield target</li><li><b>Stegosaurus:</b> spinner, upper loop, Supply Drop target</li><li><b>Spinosaurus:</b> spinner, upper loop, tower ramp, helipad ramp, left ramp</li></ul>"},
 {t:"Combos from the left ramp",h:[["left_ramp",1],["pop_target",2],["right_ramp",2],["helipad",2],["supply",3],["raptor_pen",3]],b:"<ul><li><b>Triceratops:</b> left ramp, amber target</li><li><b>Brachiosaurus:</b> left ramp, right ramp, Supply Drop target</li><li><b>Raptor:</b> left ramp, helipad ramp, Raptor target</li></ul>"},
 {t:"Combos from the helipad",h:[["helipad",1],["control",2],["left_ramp",2],["right_orbit",3],["right_ramp",3]],b:"<ul><li><b>Ankylosaurus:</b> helipad ramp, Control Room</li><li><b>Spitter:</b> helipad ramp, left ramp, right loop</li><li><b>Pteranodon:</b> helipad ramp, left ramp, right ramp</li></ul>"},
 {t:"6-Way Combo",h:["spinner","upper_loop","side_ramp","helipad","left_ramp","right_ramp"],b:"<p>Shoot these six in any order, under the same rules as DNA Combos but tracked separately. The base is 250K (+50K per DNA Combo). The 2, 3, 4, 5 and 6-way combos score 1x, 2x, 8x, 20x and 40x.</p><p>That is 10M for the 6-way with no DNA Combos, and 32M with all 11. A 6-way also awards a Fossil. A red flasher on the right side shows a 2-way has been hit, and stays on until the combo ends.</p>"},
 {t:"Trifecta Award",h:[["rescue",0,"alt"]],b:"<p>Bonuses for capturing a dinosaur and getting its fossil and DNA strand, with more for its Perfect Paddock.</p>"+UNK("The rulesheet gives no values.")}
]},
{g:"Other features",id:"save",title:"Outlanes, Extra Balls and bonus",steps:[
 {t:"Escape",h:["outlane_l","escape_ins","escape_tgt"],b:"<p>The rollover at the top entrance to the bumpers lights the far left Light Escape standup, on default settings for 20 seconds. Hitting it in time lights the Escape ball save in the left outlane. The timer falls by 4 seconds each time, to a minimum of 6.</p><p>Super Escape lights Escape for the rest of the ball.</p>"},
 {t:"Nedry",h:["outlane_r","nedry_ins","lite2x"],b:"<p>If lit, a system malfunction saves balls down the right outlane. Light it by hitting the Lite 2x Scoring standup enough times (3, 15 or 30). Progress does not resume until it has been used. The outlane also scores a small bonus that rises with more shots to that target.</p>"},
 {t:"Extra Balls",h:["right_ramp",["ramp_panel",0,"alt"],["p_trex",0,"alt"]],b:"<p>Six can be collected.</p><p><b>Lit at the right ramp:</b> 6 rescues, or 6 DNA Combos (adjustable).</p><p><b>Awarded instantly:</b> capturing the T-Rex, Smart Missile, Fossil Set 2, or the Super Supply Drop.</p><p>If set to points, they score 15M, which can be doubled.</p>"},
 {t:"End-of-ball bonus",h:[["rescue",0,"alt"]],b:"<p>Based on the whole game so far:</p><ul><li>Amber Bonus (base value only)</li><li>Rescues x 150K</li><li>Dinos captured x 500K</li><li>Fossils x 2M</li><li>DNA Combos x 400K</li></ul><p>Multiplied by Bonus X, earned from Super Predators or total rescues.</p>"}
]},
{g:"Other features",id:"fossils",title:"Fossils",steps:[
 {t:"Sets 1 and 2",h:[["trex",0,"alt"],["control",0,"alt"],["raptor_pen",0,"alt"]],b:"<p>11 Fossils in four sets. Bonus is 2M per Fossil, and all eleven award 500M.</p><p><b>Set 1</b> (20M and +10x Pteranodon multiplier):</p><ul><li>Brachiosaurus: complete your 1st T-Rex Event</li><li>Ankylosaurus: collect a Raptor Super Jackpot</li></ul><p><b>Set 2</b> (35M and Extra Ball):</p><ul><li>Velociraptor: complete your 2nd T-Rex Event</li><li>Gallimimus: complete your 1st Control Room mode</li><li>Spinosaurus: collect a letter jackpot in Chaos phase 2</li></ul>"},
 {t:"Sets 3 and 4",h:[["visitor",0,"alt"],["museum",0,"alt"],["secure",0,"alt"]],b:"<p><b>Set 3</b> (100M and +10x Amber Bonus):</p><ul><li>T. Rex: complete your 3rd T-Rex Event</li><li>Triceratops: complete your 2nd Control Room mode</li><li>Dilophosaurus: complete your 3rd Control Room mode</li></ul><p><b>Set 4</b> (250M and +10 Rescues):</p><ul><li>Compsognathus: win Museum Mayhem</li><li>Pteranodon: win Visitor's Center</li><li>Stegosaurus: win Secure Control Room</li></ul>"},
 {t:"Wildcard Fossils",h:[["upper_loop",0,"alt"],["side_ramp",0,"alt"],["right_ramp",0,"alt"]],b:"<p>Seven wildcards spot a Fossil in the lowest available set. A spotted Fossil can no longer be earned normally. Sources:</p><ul><li>Smart Missile</li><li>6-Way Combo</li><li>30 rescues (fewer with the Ankylosaurus perk)</li><li>25 tower shots</li><li>28 loops (fewer with the Triceratops perk)</li><li>A 50M+ Pteranodon Attack award</li><li>All 11 DNA Combos</li></ul>"}
]},
/* ====== WIZARD MODES ====== */
{g:"Wizard modes",id:"visitor",title:"Visitor's Center",steps:[
 {t:"Starting",h:["left_ramp","visitor","map_panel"],b:"<p>You get one attempt at each mini-wizard mode. Play all three to qualify Escape Nublar. Completing all three is required for the final wizard mode.</p><p>Reach the Visitor Center through the paddocks, lit at the left ramp by white arrows. A bonus is awarded first: Fossils x 5M, rescues x 750K, longest streak x 1.5M and DNA Combos x 2.5M, all times the paddocks visited. 2x scoring does not affect it.</p>"},
 {t:"Luring raptors",h:[["right_orbit",1],["helipad",1],["right_ramp",2],["left_ramp",3],["raptor_pen",4],["control",5]],b:"<p>Two-ball multiball with a generous ball save. The two rightmost shots, O and S, are lit. Making either moves both one position left. They score 2M x paddocks visited, +1M each time. If you wait too long, they drift back right, and a repeated shot is worth half its last value.</p>"+UNK("The numbers show the order I read from the rulesheet, using my CHAOS shot matching.")},
 {t:"Locking raptors",h:[["raptor_pen",1],["control",2]],b:"<p>At the pen, only its back target is lit. Shooting it stuns the raptor, locks the ball and serves another. The C lane does the same. Both score 4M x paddocks visited.</p><p>A hurry-up then counts down from 8M x paddocks visited. Knock either locked ball with a new ball to lock a raptor in cold storage, which frees that ball and scores the hurry-up. Lock both before it expires to win.</p><p data-ed=\"pro\">The Pro's pen cannot trap balls, so hitting the pen is enough.</p>"},
 {t:"Victory Targets",h:["control",["purple",0,"alt"]],b:"<p>Winning starts Victory Targets, for 1M (+250K) per target until multiball ends. Shoot every flashing target to light the Control Room for a jackpot and add-a-ball, and the targets relight. The Pteranodon Fossil is awarded after you drain out.</p><p>If you drain to one ball before reaching the raptor locks, the mode does not end. Once you make the first lock shot, you must complete the locks in multiball to win.</p>"}
]},
{g:"Wizard modes",id:"museum",title:"Museum Mayhem",steps:[
 {t:"Starting",h:["truck","left_ramp","museum"],b:"<p>Play all four T-Rex Events, spell T-REX at the truck once more, and shoot the left ramp.</p>"},
 {t:"Hunting raptors",h:["right_orbit","left_ramp","raptor_pen"],b:"<p>Single ball. Two green shots, the raptors, start at the right orbit and left ramp. They move one shot left about every 5 seconds, even while you cradle, so you can wait for a shot you like.</p><p>Nail one for 5M, which lights the center Raptor Pen target for 10M, then the left ramp for 20M.</p><p data-ed=\"premium\">The T-Rex throws the ball in a random direction during this mode if the left ramp is lit.</p>"},
 {t:"Escaping the museum",h:[["truck",1],["left_ramp",2]],b:"<p>After both raptors, the truck lights for 10M, then the left ramp for 75M. A 3-ball multiball then starts, with all shots lit for jackpots from 3M (+250K). The Compsognathus Fossil is awarded after you drain out.</p>"}
]},
{g:"Wizard modes",id:"secure",title:"Secure Control Room",steps:[
 {t:"The hurry-ups",h:[["left_ramp",1],["right_ramp",2],["side_ramp",3],["right_orbit",4],["upper_loop",5],["helipad",6],["pop_target",7],["control",8],["secure",0,"alt"]],b:"<p>After all three Control Room modes, shoot the Control Room again. Single ball. One shot is lit for a hurry-up, and collecting it lights a higher one on the next shot, in this fixed order:</p><ol><li>Left ramp</li><li>Right ramp</li><li>Tower ramp</li><li>Right orbit</li><li>Upper loop</li><li>Helipad</li><li>Pops target</li><li>Control room</li></ol>"},
 {t:"Finishing",h:["control",["secure",0,"alt"]],b:"<p>When each new hurry-up lights, shots you have already collected turn green for one shot. A green shot adds 5 seconds and slightly builds the current hurry-up.</p><p>Collect them all to light the Control Room lane for the sum of all hurry-ups, finishing the mode and awarding the Stegosaurus Fossil.</p>"}
]},
{g:"Wizard modes",id:"nublar",title:"Escape Nublar",steps:[
 {t:"Starting",h:["left_ramp","nublar"],b:"<p>After the three mini-wizard modes, shoot the left ramp. Navigate back through the paddocks to the main gate, rescuing remaining staff and dinosaurs before the volcano erupts.</p><p>Single ball, with three trucks as lives. A tilt is an immediate loss and ends your game, but warnings refill when you lose a truck.</p>"},
 {t:"Rescue phase",h:["rescue",["trap_l",0,"alt"],["trap_r",0,"alt"],["raptor_pen",0,"alt"],["truck",0,"alt"]],b:"<p>Hit all lit rescue shots, for 500K x rescues before Nublar + 1M x streak. The center Raptor Pen target doubles this. Once they are gone, no more appear.</p><p>If you did not capture this paddock's dinosaur earlier, hit the Set Trap targets to rescue it. A paddock you did not visit has more rescues. Turning the truck shifts remaining rescues one left or right.</p>"},
 {t:"Navigate phase",h:["left_ramp","truck"],b:"<p>Several red arrows are lit, which may or may not reveal a safe way out. If lava blocks the path, shoot another. You cannot tell in advance, and bad paths get more likely as you go. A safe path lights the left ramp. The truck's direction picks the next paddock, and you can change it before shooting the ramp.</p>"},
 {t:"Sudden Death",h:["left_ramp"],b:"<p>If the truck runs out of fuel, all lit rescues and any capture are lost, and you have 15 seconds to leave the paddock or lose that truck. You go to the Navigate phase if you were not already there. You cannot add fuel. Exit in time and the truck refuels, you move on and your streak stays.</p>"},
 {t:"Helipad Hurry-Up",h:["helipad","main_gate"],b:"<p>Back through the main gate, the helipad lights a hurry-up based on rescues, dinosaurs captured and paddocks cleared. Shoot it to escape. You also collect an island bonus based on paddocks covered, from about 125M to 550M.</p><p>Win or lose, your game ends after this mode, unless you qualified When Dinosaurs Ruled the Earth, which then ends it.</p>"}
]},
{g:"Wizard modes",id:"wdrte",title:"When Dinosaurs Ruled the Earth",steps:[
 {t:"Final wizard mode",h:ALL,b:"<p>The secret final mode, for completing Visitor's Center, Museum Mayhem, Secure Control Room and Escape Nublar.</p><p>A 60-second, 6-ball multiball with unlimited ball save. All Amber features run, scoring half your Amber value, and all shots are lit for jackpots of about 1.5x your Amber value. When time runs out, all balls drain and your game ends.</p>"}
]},
/* ====== MODES OF PLAY ====== */
{g:"Game modes",id:"modes",title:"Modes of play",steps:[
 {t:"Choosing a mode",h:[["flippers",0,"alt"]],b:"<p>Hold both flipper buttons during attract mode until a menu appears.</p><ul><li><b>Standard:</b> the full game.</li><li><b>Competition:</b> the same with randomness removed.</li><li><b>Escape Nublar Challenge:</b> a modified Escape Nublar, also with a competition version.</li><li><b>Cooperative:</b> all progress is saved between players.</li><li><b>Team Play:</b> teams share all progress.</li><li><b>DJ Mixer:</b> not gameplay. A jukebox of the game's music.</li></ul>"},
 {t:"Competition install",h:[["truck",0,"alt"]],b:"<ul><li>Escape is not lit at the start of the game.</li><li>Feed T-Rex is not fixed as the first mode, and will not start with the captive ball hit that awards the X in T-REX.</li><li>Amber awards from Super Supply Drops are in a set order, pops first.</li><li>Invalid Frenzy cannot be chosen on the Smart Missile.</li></ul>"+UNK("The rulesheet does not give the rest of the Amber order.")}
]}
];
